                // that p0 must satisfy: number of pairs whose BOTH dolls are
                // < i... which is exactly q from previous layer with pair-ending
                // <= i-1. This is encoded in vals[u][x] already through x's range.
                // We therefore recompute with q per pair-ending case in a second
                // pass below using preA[u][x] and preB[u][x].
            }

            // Full handling of x <= k-1 cases, split per pair-ending case:
            // We need prefix-min structures over look for rows u >= 1.
            // For row u >= 1: prefix over x of look[u][x].
            long[] suffU = new long[maxU + 1];
            // For case "i is a-end (q pairs fully inside, i.e., this pair not counted
            // in q)": pair cost needs old a-value = t[oldApos(u)].
            // oldApos(u): position of the u-th largest a among t[0..i-1] where two
            // of the top u are c-slots that may exchange with pair dolls; with
            // doubles c-slots exchangeable, the candidate old a-values are the
            // (u+2)-th..(u)-th largest overall; the best is t[i - u - 1] (the
            // (u+1)-th largest), and second candidate t[i-u-2] (for when the top
            // u+1 slots include both a c-slot and the current doll as pair b).
            // We evaluate both options per transition.

            // Precompute prefix arrays of look for each u (over x in [0..k]).
            long[][] prefLook = new long[maxU][];
            for (int u = 0; u < maxU; u++) {
                long[] pr = new long[k + 1];
                pr[0] = look[u][0];
                for (int x = 1; x <= k; x++) pr[x] = Math.min(pr[x - 1], look[u][x]);
                prefLook[u] = pr;
            }

            // --- case: i is a-end of pair number q+1, b later (q pairs fully inside)
            // dp -> nvals[u][x], u in [1..k], x in [0..k-1]
            // source: look[u][x + 1] restricted x+1 <= k-1... wait x in [0..k-1]:
            for (int u = 1; u <= k; u++) {
                if (d >= u - 1) {
                    // base q: pairs fully inside among first i-1 with the u-th pair
                    // having bpos <= i-1: that's q pairs; here q relates to x via
                    // x = c-slots within [somecount, i-1] covering u pairs: the
                    // constraint gives q >= u - 1 - x_prev... The two cases (q vs
                    // q+1) are distinguished by whether the pair's b is at i-1 or
                    // later; we handle by trying both a-value candidates:
                    // candidate A1: min over look[u][x+1] (with x in [0..k-1]) ->
                    //   for each x: prefix min over look[u][y] for y >= x+1.
                    // This is the "pair b > i-1" family restricted appropriately;
                    // a-value: t[i - u - 1] if doubles >= u (c-slots at top may
                    // all be exchanged or not).
                    if (doubles >= u) {
                        long c2 = (long) (t[i] - t[i - u - 1]) * (t[i] - t[i - u - 1]);
                        // x-loop: nvals[u][x] = min over sources; we need for each x
                        // the min of look[u][x+1..k]; precompute suffix of look row u
                        long[] rowS = new long[k + 2];
                        long r2 = Long.MAX_VALUE / 4;
                        int lo2 = lowerBound(t, t[i], i);
                        // e-values per x: only x >= u-1-k+d+p0(+1 if b at i-1) valid
                        // We fold validity: for source y = x+1, valid iff
                        // x+1 >= u-1-k+d+p0 (+1 if b at i-1 -> +2? no)
                        // We'll do direct loop with early break; k small relative? worst O(k^2)
                        // Too slow in worst case; instead we note validity x >= u-1-k+d+p0;
                        // p0 unknown (q or q+1)... We choose to enumerate p0's two cases
                        // via the a-value candidates as approximation -> this approach
                        // is getting unwieldy; fallback robust method below.
                    }
                }
            }

            // Fallback robust computation for x <= k-1 rows (O(k) per u amortized
            // via prefix arrays), using validity bounds with both p0 cases merged
            // conservatively by iterating the two a-value candidates and validity
            // bounds for each:
            for (int u = 1; u <= k; u++) {
                if (d < u - 1) continue;
                if (doubles < u) {
                    // c-slots at top can't all be c: exchanges change counts; still
                    // covered by candidate old a-values:
                }
                int lo2 = lowerBound(t, t[i], i);
                // Option 1: all top u c-slots enter cntC as c's:
                //   valid x: x >= u - 1 - k + d + q, q = pairs fully inside;
                //   a-value = t[lo2 - u]; q unknown in [max(0,u-1-x-d)... 
                // We handle [x in 0..k-1] via prefix/suffix merging:
                // For each x, sources: look[u][y], y = x+1..k-? with validity
                // y >= u-1-k+d+q (case pair b later: pair not in q -> q pairs),
                // y >= u-k+d+q (case pair b at i-1: q = pairs fully inside +1?? 
                // ...
                // Simplify: since p0 (pairs fully inside) satisfies
                // p0 >= u - 1 - x_prev and also p0 >= u - x (case2), the validity
                // region per y: y >= u-1-k+d+q1 or y >= u-k+d+q2 where q1, q2 are
                // consistent pair counts; both cases give constraints
                // y >= u-k+d+p where p = pairs fully inside = q2 = q1+? ...
                // The dominating constraint is y >= u - k + d + p_case where
                // p_case = pairs fully inside under that case.
                // For case1 (i is a-end): p = q, and pair (u-th) b later:
                //   lower bound: y >= u-1-k+d+q with q >= u-1-y -> y >= u-1-k+d+u-1-y -> 2y >= u-1-k+d+u-1
                // This mutual recursion is resolved because vals[u][x] itself was
                // only defined for feasible x; hence filtering by validity is
                // automatic via INF values!! So we can just take min over
                // look[u][x+1..k] without re-checking validity (infeasible sources
                // are INF). EXCEPT the "+p0" in the bound interacts with which
                // pairs counted; but since vals already encodes consistent counts,
                // we take source as look[u][x+1] family and let INF handle it.
                long[] rowArr = look[u];
                // suffix min of rowArr from x+1..k
                // compute per x via a precomputed suffix array
                long[] suf = new long[k + 2];
                suf[k] = rowArr[k];
                for (int x2 = k - 1; x2 >= 0; x2--) suf[x2] = Math.min(rowArr[x2], suf[x2 + 1]);
                // candidate a-values: t[i-u-1] (c-slots all c), or t[i-u-2] if
                // doubles >= u (one c-slot exchanged... covered by other u-row)
                if (lo2 - u >= 0) {
                    long cA = (long) (t[i] - t[lo2 - u]) * (t[i] - t[lo2 - u]);
                    if (u >= 2 && doubles >= u) {
                        // alternative: if among top u+1 slots one is the b-end (doll
                        // at i-1 as pair b), old a = t[lo2 - u - 1], covered by
                        // transition from row u+? handled in case2 below.
                    }
                    for (int x = 0; x <= k - 1; x++) {
                        long src = suf[x + 1];
                        if (src >= Long.MAX_VALUE / 4) continue;
                        long cand = src + cA;
                        if (cand < nvals[u][x]) nvals[u][x] = cand;
                    }
                }
                if (doubles >= u && lo2 - u - 1 >= 0) {
                    long cB = (long) (t[i] - t[lo2 - u - 1]) * (t[i] - t[lo2 - u - 1]);
                    for (int x = 0; x <= k - 1; x++) {
                        long src = suf[x + 1];
                        if (src >= Long.MAX_VALUE / 4) continue;
                        long cand = src + cB;
                        if (cand < nvals[u][x]) nvals[u][x] = cand;
                    }
                }
                // case2: i is b-end of the (q+1)-th pair: source look[u-1][x+1],
                // cost (t[i] - oldA)^2 where oldA = a-value of that pair:
                // oldA candidates: t[lo2-u] (top u c-slots: u-1 c-slots above the
                // pair's a were c... one of the top-u c-slots is the pair's b-end
                // (doll i-1), so old a = t[lo2 - u]) or t[lo2-u-1] (when another
                // doll between).
                if (d >= u) {
                    int lam = u - 1 - k + d + (1); // p0=q+1 pairs fully inside... the
                    // q+1-th pair's b at i-1 means q+1 pairs have bpos <= i-1:
                    // validity for old state: x+1 >= (u) - 1 - k + d + (q+1) - 1?
                    // Using INF mechanism as above: take min over look[u-1][x+1..].
                    long[] rowArr2 = look[u - 1];
                    long[] suf2 = new long[k + 2];
                    suf2[k] = rowArr2[k];
                    for (int x2 = k - 1; x2 >= 0; x2--) suf2[x2] = Math.min(rowArr2[x2], suf2[x2 + 1]);
                    if (lo2 - u >= 0) {
                        long cA = (long) (t[i] - t[lo2 - u]) * (t[i] - t[lo2 - u]);
                        for (int x = 0; x <= k - 1; x++) {
                            long src = suf2[x + 1];
                            if (src >= Long.MAX_VALUE / 4) continue;
                            long cand = src + cA;
                            if (cand < nvals[u][x]) nvals[u][x] = cand;
                        }
                    }
                    if (doubles >= u && lo2 - u - 1 >= 0) {
                        long cB = (long) (t[i] - t[lo2 - u - 1]) * (t[i] - t[lo2 - u - 1]);
                        for (int x = 0; x <= k - 1; x++) {
                            long src = suf2[x + 1];
                            if (src >= Long.MAX_VALUE / 4) continue;
                            long cand = src + cB;
                            if (cand < nvals[u][x]) nvals[u][x] = cand;
                        }
                    }
                }
            }

            // Prefix-min look for next layer: 2D
            // nlook[u][x] = min(nvals[u][0..x])
            long[][] nlook = new long[maxU][maxV];
            for (int u = 0; u < maxU; u++) {
                nlook[u][0] = nvals[u][0];
                for (int x = 1; x <= k; x++) nlook[u][x] = Math.min(nlook[u][x - 1], nvals[u][x]);
            }

            vals = nvals;
            look = nlook;
        }

        System.out.println(vals[0][0]);
    }

    static int lowerBound(int[] a, int key, int hi) {
        int lo = 0;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < key) lo = mid + 1; else hi = mid;
        }
        return lo;
    }
